//! ko-pii 문자 정규화표 — **자동 생성 파일이니 손으로 고치지 말 것.**
//!
//! scripts/gen_pii_fold.py 가 ko-pii 에 글자를 하나씩 넣어 '실제로 무엇이 되는지'
//! 물어서 뽑았다. ko-pii 의 _CHAR_FOLD 를 베끼지 않은 이유는 그 표가 NFKC 뒤에
//! 적용돼 실제 효과가 표와 다른 항목이 있기 때문이다(자세한 사정은 생성기 헤더).
//!
//! 갱신: ko-pii 버전을 올렸다면 `python scripts/gen_pii_fold.py` 로 다시 뽑는다.
//! `--check` 로 최신인지 확인할 수 있고, 어긋나면 골든 테스트가 먼저 깨진다.
//!
//! 생성 기준: ko-pii 1.15.2 / 훑은 범위 U+0000~U+2FFFF
//! 항목 수: 지움 108 · 1:1 4416 · 1:N 1179 · 표시범위 195

/// 이 표가 손댈 글자가 있는 페이지(코드포인트>>8)인가 — 이진탐색 전 O(1) 사전거름.
/// 한글 음절 페이지는 여기 없어서, 한국어 본문은 탐색을 아예 타지 않는다.
